print()
# ORF finder both strands
comp = str.maketrans("ACGT", "TGCA")
def revcomp(s): return s.translate(comp)[::-1]
stops = {"TAA","TAG","TGA"}
def orfs(s, min_aa=60):
    out = []
    for strand, ss in (("+", s), ("-", revcomp(s))):
        for f in range(3):
            i = f
            while i < len(ss)-2:
                if ss[i:i+3] == "ATG":
                    j = i
                    while j < len(ss)-2 and ss[j:j+3] not in stops:
                        j += 3
                    if j < len(ss)-2:
                        aa = (j-i-3)//3
                        if aa >= min_aa:
                            if strand=="+":
                                st, en = i+1, j+3
                            else:
                                st, en = len(ss)-(j+3)+1, len(ss)-i
                            out.append((strand, st, en, aa))
                    i = j
                i += 3
    return out
o = sorted(orfs(seq), key=lambda x: x[1])
for strand, st, en, aa in o:
    print(strand, st, en, f"{aa}aa")
